# Citation Network Analyzer - runnable demo (JAH-ATK188S-000001)
RANK = 1
SIG = True
EDGES = [('p1', 'p3'), ('p2', 'p3'), ('p3', 'p4'), ('p1', 'p4'), ('p4', 'p5')]  # (citer, cited)
nodes = sorted({n for e in EDGES for n in e})
pr = {n: 1.0/len(nodes) for n in nodes}
outdeg = {n: 0 for n in nodes}
for a, b in EDGES: outdeg[a] += 1
for _ in range(20):
    new = {}
    for n in nodes:
        s = sum(pr[a]/outdeg[a] for a, b in EDGES if b == n and outdeg[a] > 0)
        new[n] = 0.15/len(nodes) + 0.85*s
    pr = new
ranked = sorted(pr.items(), key=lambda x: -x[1])
print("papers:", len(nodes), "| citations:", len(EDGES))
for n, score in ranked:
    cites = sum(1 for a, b in EDGES if b == n)
    print("  %-6s influence=%.3f citations=%d" % (n, score, cites))
if RANK >= 3:
    hubs = sorted(nodes, key=lambda n: outdeg[n], reverse=True)[:2]
    print("most citing (hubs):", hubs)
if SIG:
    print("Signature lineage stamp: JAH-SIG-CIT-" + "JAH-ATK188S-000001")
print("record:", "JAH-ATK188S-000001", "OK")

